@mixin effect-normal() {
    @include border-radius(1px);  
    @include box-shadow-multiple('0 3px 6px rgba(0,0,0,.16),0 3px 6px rgba(0,0,0,.23)'); 
}

@mixin effect-special() {
    @include border-radius(1px); 
    @include box-shadow-multiple('0 10px 20px rgba(0,0,0,.19),0 6px 6px rgba(0,0,0,.23)'); 
}

@mixin effect-textbox() {
    @include border-radius(1px);
    @include box-shadow(0px, 1px, 1px, rgba(0, 0, 0, 0.3));
}

@mixin effect-button() {
    @include border-radius(1px);
    @include box-shadow(0px, 2px, 2px, rgba(0, 0, 0, 0.3));
}

