$msg-error-bg: #fadddd;
$msg-error-color: #fe0000;
$msg-error-border: #ef2d2d;

$msg-success-bg: #eefbe9;
$msg-success-color: #52a220;
$msg-success-border: #1db51a;

.form-validation {
    %alphaIcon {
        font:{
            family: 'Iconalpha';
            style: normal;
        }
    }

    .form-group {
        position: relative;
    }

    .txt {
        &.error ~ .validation, &.valid ~ .validation {
            @extend %alphaIcon;
            font-size: 18px;
            right: 8px;
            top: 25px;
            position: absolute;
        }

        &.error {
            ~ .validation:before {     
                content: '\e92c';
                color: $msg-error-color;
            }
        }

        &.valid {
            ~ .validation:before {
                content: '\e91f';
                color: $msg-success-color;
            }
        }
    }
}

