    $msg-success-color: #52a220;
    $msg-success-border: #1db51a;

    $msg-warning-bg: #faf8dd;
    $msg-warning-color: #7e3d00;
    $msg-warning-border: #bcba7d;
    $msg-warning-icon-color: #f08708;

    $msg-error-bg: #fadddd;
    $msg-error-color: #fe0000;
