    // icons
    %icon {
        background: url(assets/img/login-sprites.png) no-repeat;
        display: inline-block;
    }

    .icon-user {
        @extend %icon;
        background-position: -54px -4px;
        height: 14px;
        width: 14px;
    }

    .icon-lock {
        @extend %icon;
        background-position: -78px 0;
        height: 19px;
        width: 14px;
    }

    .icon-refresh {
        @extend %icon;
        background-position: -28px -3px;
        cursor: pointer;
        height: 16px;
        width: 16px;

        &:hover {
            background-position: -28px -29px;
        }
    }

    .icon-captcha {
        @extend %icon;
        background-position: -26px -50px;
        height: 34px;
        width: 89px;
    }

