        @extend %icon;
        width: 23px;
        height: 16px;
        position: relative;
        top: 4px;
        margin-right: 2px;

        &.flag-en {
            background-position: 0 0px;
        }
        &.flag-cn {
            background-position: 0 -17px;
        }
        &.flag-tw {
            background-position: 0 -34px;
        }
        &.flag-jp {
            background-position: 0 -50px;
        }
        &.flag-th {
            background-position: 0 -69px;
        }
        &.flag-kr {
            background-position: 0 -86px;
        }
        &.flag-vn {
            background-position: 0 -104px;
        }
    }

    .block {
        width: 360px;
        max-width: 400px;
        background: $block-bg;
        padding: 40px 30px;    
        margin: auto;
        @include box-sizing;
        @include box-shadow-multiple('0px 2px 2px rgba(0, 0, 0, 0.3)');
    
