        top: 0;
        width: 100%;
        @include box-shadow-multiple('0px 2px 2px rgba(0, 0, 0, 0.3)');

        .content {
            margin: auto;
            padding: 12px 36px 12px 36px;
            width: 606px;
            position: relative;

            p {
                margin-bottom: 4px;
            }

            &:before {
                @extend %icon;
                background-position: -85px -93px;
                height: 23px;
                width: 30px;
                content: '';
                position: absolute;
                left: 0;
            }

            a {
                color: $link-color;
                font-weight: bold;
                text-decoration: underline;
                &:hover {
                    color: $link-hover-color;
                }
            }

            .icon-close {
                @extend %icon;
                background-position: -46px -100px;
                cursor: pointer;
                height: 12px;
                width: 13px;
                position: absolute;
                right: 0;
                top: 12px;

                &:hover {
                    opacity: 0.7;
                }
            }
        }
    }

    @media only screen and (max-device-width: 767px)
    {  
       body {
          font-size: $font-size + 3;
          padding-top: 0;
          background-color: $block-bg;
       }

       .block {
            padding: 0 30px;
            width: 100%;
            @include box-shadow-multiple(none);

            .rowlg {
                margin-bottom: 20px;
            }

            .box-lang {
                padding-top: 8px;
                padding-bottom: 4px;
            }

            .title {
                margin: 4px 0 12px;
            }

            .list-button {
                padding-top: 0;
            }
        }

       .block-warning {
           position: relative;
           .content {
               padding: 12px 48px;
               width: 100%;

               &:before {
                    margin-left: 12px;
               }

               .icon-close {
                   right: 12px;
               }
           }
       }
    }

    @media only screen and (max-device-width: 374px)
    {  
       body {
          font-size: $font-size;
       }

       .block {
            padding: 0 30px;
            width: 100%;
            @include box-shadow-multiple(none);

            .rowlg {
                margin-bottom: 16px;
            }

            .title {
                margin: 4px 0 4px;
                font-size: $font-size + 7;
            }

            .list-button {
                padding-top: 0;
            }
        }
    }
}

