@font-face {
    font-family: 'Iconalpha';
    src:    url('../../Fonts/Iconalpha/fonts/Iconalpha.eot');
    src:    url('../../../Fonts/Iconalpha/fonts/Iconalpha.eot#iefix') format('embedded-opentype'),
        url('../../Fonts/Iconalpha/fonts/Iconalpha.ttf') format('truetype'),
        url('../../Fonts/Iconalpha/fonts/Iconalpha.woff') format('woff'),
        url('../../Fonts/Iconalpha/fonts/Iconalpha.svg#Iconalpha') format('svg');
    font-weight: normal;
    font-style: normal;
}

.pagingContainer {
    text-align: center;
    list-style: none;
    margin: 0;
    padding-top: 8px;
    padding-bottom: 8px;

    li {
        display: inline-block;
        margin: 0 2px;

        &[disabled] .btn-page {
            background-color: $paging-btn-bg;
            opacity: 0.35;
            cursor: default;

            &:hover {
                background-color: $paging-btn-bg;
                opacity: 0.35;
            }
        }

        &.pagingSeperator {
            border-left: 1px solid #ccc;
            margin: 0 6px;
            width: 1px;
            height: 18px;
        }

    }

    * {
        vertical-align: middle;
    }

    .btn-page {
        width: 20px;
        height: 20px;
        line-height: 20px;
        background-color: $paging-btn-bg;
        display: inline-block;
        cursor: pointer;    
        outline: none;
        position: relative;
        @include border-radius(2px);
        @include box-sizing;

        &:hover {
            background-color: $paging-btn-bg-hover;
        }

        &:before {
            font-family: Iconalpha;
            font-size: 15px;
            color: $paging-btn-color;
        }

        &.pagingDisable, &.pagingDisable:hover {
            cursor: default;
            filter: alpha(opacity=35);
            -moz-opacity: .35;
            opacity: 0.35;
        }

        &.first:before {
            content: '\e940';
        }

        &.prev:before {
            content: '\e93f';
        }

        &.last:before {
            content: '\e941';
        }

        &.next:before {
            content: '\e942';
        }
    }
}

